EchoPrivateAsyncWaiter::EchoPrivateAsyncWaiter(
    EchoPrivate* proxy) : proxy_(proxy) {}

EchoPrivateAsyncWaiter::~EchoPrivateAsyncWaiter() = default;

void EchoPrivateAsyncWaiter::CheckRedeemOffersAllowed(
    const std::string& window_id, const std::string& service_name, const std::string& origin, bool* out_allowed) {
  base::RunLoop loop;
  proxy_->CheckRedeemOffersAllowed(std::move(window_id),std::move(service_name),std::move(origin),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_allowed
,
             bool allowed) {*out_allowed = std::move(allowed);
            loop->Quit();
          },
          &loop,
          out_allowed));
  loop.Run();
}

bool EchoPrivateAsyncWaiter::CheckRedeemOffersAllowed(
    const std::string& window_id, const std::string& service_name, const std::string& origin) {
  bool async_wait_result;
  CheckRedeemOffersAllowed(std::move(window_id),std::move(service_name),std::move(origin),&async_wait_result);
  return async_wait_result;
}

void EchoPrivateAsyncWaiter::GetOobeTimestamp(
    std::string* out_timestamp) {
  base::RunLoop loop;
  proxy_->GetOobeTimestamp(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_timestamp
,
             const std::string& timestamp) {*out_timestamp = std::move(timestamp);
            loop->Quit();
          },
          &loop,
          out_timestamp));
  loop.Run();
}

std::string EchoPrivateAsyncWaiter::GetOobeTimestamp(
    ) {
  std::string async_wait_result;
  GetOobeTimestamp(&async_wait_result);
  return async_wait_result;
}

void EchoPrivateAsyncWaiter::GetRegistrationCode(
    RegistrationCodeType type, std::string* out_result) {
  base::RunLoop loop;
  proxy_->GetRegistrationCode(std::move(type),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_result
,
             const std::string& result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

std::string EchoPrivateAsyncWaiter::GetRegistrationCode(
    RegistrationCodeType type) {
  std::string async_wait_result;
  GetRegistrationCode(std::move(type),&async_wait_result);
  return async_wait_result;
}






